def fit(extra_fn, name):
    best=None
    for c0 in [-0.5,0.1,1.0]:
      for e0 in [0.05,0.3,1.0]:
        def resid(p):
            X=np.c_[1/eps, eps/(1+p[0]*eps)*T**3, T**2/(1+p[1]*T**2)/eps]
            if extra_fn is not None:
                X=np.c_[X, extra_fn(p[2:])]
            coef=np.linalg.lstsq(X,s,rcond=None)[0]
            return s-X@coef
        try:
            npar=2+(0 if extra_fn is None else 1)
            r=least_squares(resid,[c0,e0,0.5][:2+ (1 if extra_fn is not None else 0)] if False else np.r_[c0,e0,np.ones(npar-2)*0.5][:npar])
            v=np.mean(r.fun**2)/np.var(s)
            if best is None or v<best[0]: best=(v,r.x)
        except Exception as ex:
            pass
    print(name,best)
